INSERT INTO t_p71821556_real_estate_catalog_.category_texts (category_type, h1, h2, h3, h4, h5, description, features) VALUES
('office', 'Аренда и продажа офисов в Краснодаре', 'Офисные помещения в Краснодаре — подбор под ваш бизнес', 'Аренда офисов в Краснодаре', 'Офисы в бизнес-центрах и отдельных зданиях', 'Параметры и цены на офисы', 'Офисные помещения в Краснодаре на любой бюджет — от небольших кабинетов до целых этажей в бизнес-центрах. Помогаем подобрать офис в центре города, деловых кварталах или на периферии с удобной парковкой.', '["Помещения от 15 до 3000 м²", "Бизнес-центры класса A, B и C", "Открытая планировка и кабинетная", "Инфраструктура: переговорные, кухни, reception"]'),
('retail', 'Торговые помещения в аренду и продажу в Краснодаре', 'Торговые площади в Краснодаре — первая линия и ТЦ', 'Торговые площади в аренду в Краснодаре', 'Магазины и шоурумы в торговых центрах', 'Параметры и условия аренды торговых помещений', 'Торговые площади на первых линиях улиц, в торговых центрах, жилых комплексах и отдельно стоящих зданиях. Идеально для магазинов, шоурумов, аптек и бутиков.', '["1-я и 2-я линия улиц", "Витринные окна и отдельные входы", "Высокий пешеходный и автомобильный трафик", "Помещения с готовым торговым оборудованием"]'),
('warehouse', 'Складские помещения в аренду в Краснодаре', 'Склады и складские комплексы в Краснодаре и пригороде', 'Аренда складов в Краснодаре', 'Отапливаемые и холодильные склады', 'Площади и ставки аренды складских помещений', 'Современные склады и складские комплексы в Краснодаре и пригороде — от небольших боксов до логистических центров. Удобный подъезд для фур, ворота секционные, охрана.', '["Стеллажное хранение и ответственное хранение", "Ворота с пандусом и рампой", "Отапливаемые и холодильные склады", "Охраняемая территория и видеонаблюдение"]'),
('restaurant', 'Помещения под кафе, рестораны и общепит в Краснодаре', 'Открыть кафе или ресторан в Краснодаре — готовые помещения', 'Рестораны и кафе на продажу в Краснодаре', 'Помещения с вентиляцией и вытяжкой для общепита', 'Цены и условия аренды помещений под общепит', 'Готовые и чистовые помещения для открытия кафе, ресторанов, баров, пекарен и фастфуда в Краснодаре. Объекты с вытяжкой, электрической мощностью и разрешённым использованием.', '["Готовые кухни и вентиляция", "Высокий трафик и парковка", "Наружная реклама и вывески", "Помещения с действующим бизнесом"]'),
('hotel', 'Гостиницы и мини-отели в продажу и аренду в Краснодаре', 'Гостиничный бизнес в Краснодаре — продажа и аренда', 'Мини-отели и хостелы в Краснодаре', 'Действующие гостиницы с персоналом и клиентской базой', 'Номерной фонд, загрузка и доходность отелей', 'Действующие и готовые к запуску гостиницы, мини-отели, хостелы и апарт-отели в Краснодаре. Готовые бизнесы с персоналом и клиентской базой.', '["Готовый гостиничный бизнес", "Апарт-комплексы и хостелы", "Объекты с документами и разрешениями", "Центральные и курортные локации"]'),
('business', 'Продажа готового бизнеса в Краснодаре', 'Готовый бизнес в Краснодаре — актуальные предложения', 'Купить готовый бизнес в Краснодаре', 'Бизнес с подтверждёнными доходами и документами', 'Стоимость и окупаемость готового бизнеса', 'Готовый бизнес с оборудованием, клиентской базой, персоналом и подтверждёнными доходами. Кафе, магазины, производства, сервисные компании — проверенные объекты с документами.', '["Подтверждённая выручка и прибыль", "Полный пакет документов", "Бизнес с историей и репутацией", "Поддержка при передаче бизнеса"]'),
('gab', 'ГАБ — готовый арендный бизнес в Краснодаре', 'Популярные категории: офисы, склады, торговые площади, рестораны', 'Инвестиции в готовый арендный бизнес', 'ГАБ с сетевыми арендаторами — Краснодар', 'Доходность и окупаемость арендного бизнеса', 'Инвестиционные объекты с действующими долгосрочными арендаторами. Стабильный пассивный доход с первого дня владения. Окупаемость 8–12 лет.', '["Арендаторы — сетевые федеральные компании", "Долгосрочные договоры аренды от 3 лет", "Прозрачная финансовая отчётность", "Окупаемость 8–12 лет"]'),
('production', 'Аренда производственных помещений в Краснодаре', 'Производственные цеха и базы в Краснодаре', 'Аренда цехов и мастерских в Краснодаре', 'Промышленные помещения с кранами и высокими потолками', 'Мощность электроснабжения и технические параметры', 'Производственные цеха, мастерские, технические базы и промышленные объекты в Краснодаре и пригороде. Высокие потолки, мощное электроснабжение, удобный подъезд для грузового транспорта.', '["Потолки от 5 до 15 метров", "Электроснабжение 3-фаза от 50 кВт", "Краны-балки и тельферы", "Промышленные зоны и отдельные въезды"]'),
('land', 'Продажа коммерческих земельных участков в Краснодаре', 'Земельные участки под коммерческое строительство', 'Продажа земли под бизнес в Краснодарском крае', 'Участки с коммуникациями и разрешёнными видами использования', 'Площадь, стоимость и категория земельных участков', 'Земельные участки под коммерческое строительство, склады, производство, торговлю в Краснодаре и Краснодарском крае. Участки с подведёнными коммуникациями и разрешённым использованием.', '["ИЖС, КФХ, промышленные категории", "Подъезд и коммуникации", "Участки с проектами застройки", "Первая линия и трассовые участки"]'),
('building', 'Продажа и аренда отдельно стоящих зданий в Краснодаре', 'Отдельно стоящие здания под офис или бизнес в Краснодаре', 'Продажа зданий в Краснодаре', 'Здания с собственной территорией и парковкой', 'Площадь, этажность и стоимость зданий', 'Административные здания, офисные центры, торговые здания и особняки под бизнес в Краснодаре. Собственная территория, парковка и независимость от управляющих компаний.', '["Собственная парковка и территория", "Независимая инфраструктура", "Возможность брендирования фасада", "Исторические и новые здания"]'),
('free_purpose', 'Помещения свободного назначения в Краснодаре', 'Универсальные коммерческие помещения в Краснодаре', 'Аренда помещений свободного назначения', 'Помещения для медицины, спорта, образования и торговли', 'Площадь и стоимость помещений свободного назначения', 'Универсальные коммерческие помещения без ограничений по виду деятельности. Подходят для медицины, образования, спорта, торговли, сервиса и многих других видов бизнеса.', '["Без ограничений по виду деятельности", "Возможна перепланировка", "На первых и цокольных этажах", "Оптимальное соотношение цена/качество"]'),
('car_service', 'Аренда и продажа помещений под автосервис в Краснодаре', 'Автосервисы и автобизнес в Краснодаре', 'Аренда боксов и помещений для автосервиса', 'Готовые автосервисы с оборудованием и клиентской базой', 'Площадь, въездные ворота и мощность электрики', 'Готовые автосервисы и помещения под автобизнес — боксы, мастерские, автомойки, шиномонтажи в Краснодаре. Въездные ворота, ямы, компрессоры, электрика под нагрузку.', '["Подъёмники и ямы в комплекте", "Въезд для легковых и грузовых ТС", "Электрика 380 В от 30 кВт", "Готовые автосервисы с клиентской базой"]')
